PAGE_CSS["panduan-wifi-kos-solo"] = "\r\n    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }\r\n    :root {\r\n      --green: #037e64;\r\n      --green-dark: #026b55;\r\n      --green-light: #e6f7f3;\r\n      --gray-bg: #f5f5f5;\r\n      --text: #1a1a1a;\r\n      --text-muted: #6b7280;\r\n      --border: #e5e7eb;\r\n      --white: #ffffff;\r\n    }\r\n    html { scroll-behavior: smooth; }\r\n    body {\r\n      font-family: 'Plus Jakarta Sans', sans-serif;\r\n      background: var(--white);\r\n      color: var(--text);\r\n      line-height: 1.6;\r\n    }\r\n    a { color: inherit; }\r\n\r\n    /* HEADER (consistent with rest of site) */\r\n    header {\r\n      background: var(--white);\r\n      box-shadow: 0 1px 3px rgba(0,0,0,.08);\r\n      position: sticky;\r\n      top: 0;\r\n      z-index: 100;\r\n    }\r\n    .header-inner {\r\n      max-width: 1200px;\r\n      margin: 0 auto;\r\n      padding: 14px 24px;\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: space-between;\r\n    }\r\n    .logo img { height: 36px; width: auto; }\r\n    nav { display: flex; align-items: center; gap: 32px; }\r\n    nav a {\r\n      font-size: 14px;\r\n      font-weight: 500;\r\n      color: var(--text);\r\n      text-decoration: none;\r\n      transition: color .2s;\r\n    }\r\n    nav a:hover { color: var(--green); }\r\n    .btn-wa-header {\r\n      background: var(--green);\r\n      color: var(--white);\r\n      padding: 10px 22px;\r\n      border-radius: 6px;\r\n      font-size: 14px;\r\n      font-weight: 600;\r\n      text-decoration: none;\r\n      display: flex;\r\n      align-items: center;\r\n      gap: 8px;\r\n      transition: background .2s;\r\n      border: none;\r\n      cursor: pointer;\r\n    }\r\n    .btn-wa-header:hover { background: var(--green-dark); }\r\n\r\n    /* ARTICLE LAYOUT */\r\n    .article-hero {\r\n      background: var(--green-light);\r\n      padding: 48px 24px;\r\n      text-align: center;\r\n    }\r\n    .article-hero .breadcrumb {\r\n      font-size: 13px;\r\n      color: var(--text-muted);\r\n      margin-bottom: 16px;\r\n    }\r\n    .article-hero .breadcrumb a { color: var(--green-dark); text-decoration: none; }\r\n    .article-hero h1 {\r\n      font-size: 32px;\r\n      font-weight: 800;\r\n      max-width: 800px;\r\n      margin: 0 auto 12px;\r\n      line-height: 1.3;\r\n    }\r\n    .article-hero .subtitle {\r\n      font-size: 16px;\r\n      color: var(--text-muted);\r\n      max-width: 640px;\r\n      margin: 0 auto;\r\n    }\r\n    .article-meta {\r\n      font-size: 13px;\r\n      color: var(--text-muted);\r\n      margin-top: 16px;\r\n    }\r\n\r\n    .article-body {\r\n      max-width: 720px;\r\n      margin: 0 auto;\r\n      padding: 48px 24px;\r\n    }\r\n    .article-body h2 {\r\n      font-size: 24px;\r\n      font-weight: 700;\r\n      margin: 40px 0 16px;\r\n      color: var(--text);\r\n    }\r\n    .article-body h2:first-child { margin-top: 0; }\r\n    .article-body h3 {\r\n      font-size: 18px;\r\n      font-weight: 700;\r\n      margin: 28px 0 12px;\r\n    }\r\n    .article-body p {\r\n      font-size: 16px;\r\n      margin-bottom: 16px;\r\n      color: #333;\r\n    }\r\n    .article-body ul, .article-body ol {\r\n      margin: 0 0 16px 24px;\r\n      font-size: 16px;\r\n      color: #333;\r\n    }\r\n    .article-body li { margin-bottom: 8px; }\r\n    .article-body strong { color: var(--text); }\r\n\r\n    .info-box {\r\n      background: var(--green-light);\r\n      border-left: 4px solid var(--green);\r\n      border-radius: 8px;\r\n      padding: 20px 24px;\r\n      margin: 24px 0;\r\n      font-size: 15px;\r\n    }\r\n    .info-box strong { color: var(--green-dark); }\r\n\r\n    .speed-table {\r\n      width: 100%;\r\n      border-collapse: collapse;\r\n      margin: 20px 0;\r\n      font-size: 14px;\r\n    }\r\n    .speed-table th, .speed-table td {\r\n      border: 1px solid var(--border);\r\n      padding: 12px 14px;\r\n      text-align: left;\r\n    }\r\n    .speed-table th {\r\n      background: var(--gray-bg);\r\n      font-weight: 700;\r\n    }\r\n\r\n    .kampus-grid {\r\n      display: grid;\r\n      grid-template-columns: repeat(2, 1fr);\r\n      gap: 12px;\r\n      margin: 20px 0;\r\n    }\r\n    .kampus-item {\r\n      background: var(--gray-bg);\r\n      border-radius: 8px;\r\n      padding: 14px 16px;\r\n      font-size: 14px;\r\n      font-weight: 600;\r\n    }\r\n    .kampus-item span {\r\n      display: block;\r\n      font-size: 12px;\r\n      font-weight: 400;\r\n      color: var(--text-muted);\r\n      margin-top: 4px;\r\n    }\r\n\r\n    .cta-box {\r\n      background: var(--green);\r\n      color: var(--white);\r\n      border-radius: 12px;\r\n      padding: 32px;\r\n      text-align: center;\r\n      margin: 40px 0;\r\n    }\r\n    .cta-box h3 { color: var(--white); margin-bottom: 8px; }\r\n    .cta-box p { color: rgba(255,255,255,.9); margin-bottom: 20px; }\r\n    .cta-box .btn-cta {\r\n      background: var(--white);\r\n      color: var(--green-dark);\r\n      padding: 14px 28px;\r\n      border-radius: 8px;\r\n      font-weight: 700;\r\n      text-decoration: none;\r\n      display: inline-flex;\r\n      align-items: center;\r\n      gap: 8px;\r\n    }\r\n\r\n    .related-cities {\r\n      display: flex;\r\n      flex-wrap: wrap;\r\n      gap: 10px;\r\n      margin: 20px 0;\r\n    }\r\n    .related-cities a {\r\n      background: var(--gray-bg);\r\n      padding: 10px 18px;\r\n      border-radius: 20px;\r\n      font-size: 14px;\r\n      font-weight: 600;\r\n      text-decoration: none;\r\n      color: var(--text);\r\n      transition: background .2s;\r\n    }\r\n    .related-cities a:hover { background: var(--green-light); color: var(--green-dark); }\r\n\r\n    /* FOOTER (consistent with rest of site) */\r\n    footer {\r\n      background: #1a1a1a;\r\n      color: rgba(255,255,255,.7);\r\n      padding: 32px 24px;\r\n    }\r\n    .footer-inner {\r\n      max-width: 1200px;\r\n      margin: 0 auto;\r\n      display: flex;\r\n      justify-content: space-between;\r\n      align-items: center;\r\n      gap: 16px;\r\n    }\r\n    .footer-left { display: flex; flex-direction: column; gap: 6px; }\r\n    .footer-logo { height: 28px; width: auto; max-width: 100%; object-fit: contain; flex: 0 0 auto; filter: brightness(0) invert(1); opacity: .7; }\r\n    .footer-copy { font-size: 12px; }\r\n    .footer-links { display: flex; gap: 20px; font-size: 13px; }\r\n    .footer-links a { color: rgba(255,255,255,.7); text-decoration: none; }\r\n    .footer-socials { display: flex; gap: 12px; }\r\n    .footer-socials a {\r\n      color: rgba(255,255,255,.7);\r\n      width: 36px; height: 36px;\r\n      display: flex; align-items: center; justify-content: center;\r\n      border: 1px solid rgba(255,255,255,.2);\r\n      border-radius: 50%;\r\n      text-decoration: none;\r\n    }\r\n\r\n    @media (max-width: 768px) {\r\n      nav { display: none; }\r\n      .article-hero h1 { font-size: 24px; }\r\n      .kampus-grid { grid-template-columns: 1fr; }\r\n      .footer-inner { flex-direction: column; }\r\n      .footer-links { flex-direction: column; gap: 12px; text-align: center; }\r\n    }\r\n  ";

